VALUE_LABELS = [
    ('ORG_TYPE', 'КОММ_ОРГ', 'Коммерческая организация'),
    ('CL_TYPE', 'CLIENT', 'Клиент банка'),
    ('CL_TYPE', 'PROSPECT', 'Потенциальный клиент'),
    ('CL_TYPE', 'CLOSE_CLIENT', 'Закрытый клиент (код набора)'),
]
FLAG_NAMES = {
    'NEGATIVEMARK':'признак ключевого собственника',
    'CL_PRODUCT_RKO_MARK':'РКО',
    'CL_PRODUCT_GAR_MARK':'банковские гарантии',
    'CL_PRODUCT_LOA_MARK':'кредитный продукт',
    'CL_PRODUCT_LEA_MARK':'лизинг',
    'CL_PRODUCT_DEP_MARK':'депозитный продукт',
    'CL_PRODUCT_ZPP_MARK':'зарплатный проект',
    'FTS_FLAG':'сведения о компании в данных ФТС',
    'FACTORING_MARK':'факторинг',
}
for flag, name in FLAG_NAMES.items():
    VALUE_LABELS.extend([(flag,'1.0',f'В наборе отмечены {name}'),
                         (flag,'0.0',f'В наборе не отмечены {name}')])

def ensure_field_labels(connection) -> None:
    connection.execute('''CREATE SCHEMA IF NOT EXISTS profile_data''')
    connection.execute('''CREATE TABLE IF NOT EXISTS profile_data.field_labels (
        field_key TEXT PRIMARY KEY,
        label TEXT NOT NULL,
        description TEXT NOT NULL,
        section TEXT NOT NULL,
        sort_order INTEGER NOT NULL
    )''')
    executemany(connection, '''INSERT INTO profile_data.field_labels
        (field_key,label,description,section,sort_order) VALUES (%s,%s,%s,%s,%s)
        ON CONFLICT(field_key) DO UPDATE SET label=excluded.label,
        description=excluded.description,section=excluded.section,sort_order=excluded.sort_order''',
        ((key,label,description,section,i) for i,(key,label,description,section) in enumerate(FIELDS)))
    connection.execute('''CREATE TABLE IF NOT EXISTS profile_data.field_value_labels (
        field_key TEXT NOT NULL,
        raw_value TEXT NOT NULL,
        label TEXT NOT NULL,
        PRIMARY KEY(field_key,raw_value)
    )''')
    executemany(connection, '''INSERT INTO profile_data.field_value_labels (field_key,raw_value,label)
        VALUES (%s,%s,%s) ON CONFLICT(field_key,raw_value) DO UPDATE SET label=excluded.label''', VALUE_LABELS)

def main() -> None:
    parser = argparse.ArgumentParser(description='Update field descriptions in PostgreSQL')
    parser.add_argument('--dsn', help='PostgreSQL DSN; defaults to PROFILE_DATABASE_URL, then DATABASE_URL')
    args = parser.parse_args()
    with connect(args.dsn) as connection:
        ensure_field_labels(connection)
    print(f'Updated {len(FIELDS)} field labels and {len(VALUE_LABELS)} value labels in PostgreSQL')

if __name__ == '__main__':
    main()
